<?php $isEdit=$mode==='edit';$action=$isEdit?url('admin/perfumes/'.$perfume['id'].'/actualizar'):url('admin/perfumes');ob_start(); ?><form class="perfume-form" method="post" action="<?=$action?>" enctype="multipart/form-data"><?=csrf_field()?><?php if($isEdit): ?><input type="hidden" name="updated_at" value="<?=e($perfume['updated_at']??'')?>"><?php endif; ?><?php if(!empty($errors)): ?><div class="admin-alert danger" role="alert"><?php foreach((array)$errors as $error): ?><div><?=e($error)?></div><?php endforeach; ?></div><?php endif; ?><section class="panel form-section"><h2>Información básica</h2><div class="form-grid"><label>Nombre *<input required maxlength="200" name="name" value="<?=e($perfume['name']??'')?>"></label><label>Slug<input name="slug" value="<?=e($perfume['slug']??'')?>" placeholder="Se genera automáticamente"></label><label>Marca<select name="brand_id"><option value="">Sin marca</option><?php foreach($options['brands'] as $o): ?><option value="<?=$o['id']?>" <?=((string)($perfume['brand_id']??'')===(string)$o['id'])?'selected':''?>><?=e($o['name'])?><?=empty($o['is_active'])?' (inactiva)':''?></option><?php endforeach; ?></select></label><label>Categoría principal<select name="category_id"><option value="">Sin categoría</option><?php foreach($options['categories'] as $o): ?><option value="<?=$o['id']?>" <?=((string)($perfume['category_id']??'')===(string)$o['id'])?'selected':''?>><?=e($o['name'])?></option><?php endforeach; ?></select></label><label>Familia olfativa<select name="olfactory_family_id"><option value="">Sin familia</option><?php foreach($options['families'] as $o): ?><option value="<?=$o['id']?>" <?=((string)($perfume['olfactory_family_id']??'')===(string)$o['id'])?'selected':''?>><?=e($o['name'])?></option><?php endforeach; ?></select></label><label>Subtítulo<input name="subtitle" value="<?=e($perfume['subtitle']??'')?>"></label><label>Género<select name="gender"><?php foreach(PerfumeValidator::GENDERS as $v): ?><option value="<?=$v?>" <?=($perfume['gender']??'no_aplica')===$v?'selected':''?>><?=e(catalog_label('gender',$v))?></option><?php endforeach; ?></select></label><label>Concentración<select name="concentration"><?php foreach(PerfumeValidator::CONCENTRATIONS as $v): ?><option value="<?=$v?>" <?=($perfume['concentration']??'otro')===$v?'selected':''?>><?=e(catalog_label('concentration',$v))?></option><?php endforeach; ?></select></label><label>Año de lanzamiento<input type="number" name="launch_year" min="1800" max="<?=date('Y')+1?>" value="<?=e($perfume['launch_year']??'')?>"></label><label>Perfumista<input name="perfumer" value="<?=e($perfume['perfumer']??'')?>"></label><label>País de origen<input name="origin_country" value="<?=e($perfume['origin_country']??'')?>"></label></div></section><section class="panel form-section"><h2>Descripciones</h2><label>Descripción corta<textarea name="short_description" maxlength="1000" rows="4"><?=e($perfume['short_description']??'')?></textarea></label><label>Descripción completa<textarea name="full_description" rows="8"><?=e($perfume['full_description']??'')?></textarea></label></section><section class="panel form-section"><h2>Disponibilidad y precio</h2><div class="form-grid"><label>Disponibilidad<select name="availability_status"><?php foreach(PerfumeValidator::AVAILABILITY as $v): ?><option value="<?=$v?>" <?=($perfume['availability_status']??'pendiente')===$v?'selected':''?>><?=e(catalog_label('availability',$v))?></option><?php endforeach; ?></select></label><label>Precio desde<input type="number" min="0" step="0.01" name="price_from" value="<?=e($perfume['price_from']??'')?>"></label><label>Texto de precio<input name="price_text" value="<?=e($perfume['price_text']??'')?>" placeholder="Consulta precio"></label></div><label><input type="checkbox" name="show_price" value="1" <?=!empty($perfume['show_price'])?'checked':''?>> Mostrar precio públicamente</label></section><section class="panel form-section"><h2>Características</h2><div class="form-grid"><label>Temporada<input name="season" value="<?=e($perfume['season']??'')?>"></label><label>Ocasión<input name="occasion" value="<?=e($perfume['occasion']??'')?>"></label><label>Intensidad<input name="intensity" value="<?=e($perfume['intensity']??'')?>"></label><label>Duración<input name="longevity" value="<?=e($perfume['longevity']??'')?>"></label><label>Estela<input name="sillage" value="<?=e($perfume['sillage']??'')?>"></label><label>Audiencia<input name="audience" value="<?=e($perfume['audience']??'')?>"></label></div><label><input type="checkbox" name="is_featured" value="1" <?=!empty($perfume['is_featured'])?'checked':''?>> Destacado</label> <label><input type="checkbox" name="is_new" value="1" <?=!empty($perfume['is_new'])?'checked':''?>> Nuevo</label> <label><input type="checkbox" name="is_promotion" value="1" <?=!empty($perfume['is_promotion'])?'checked':''?>> Promoción</label></section><section class="panel form-section"><h2>Imagen</h2><?php if($isEdit&&$relations['images']): ?><div class="admin-image-grid"><?php foreach($relations['images'] as $im): ?><figure><img src="<?=e(media_url($im['image_path']))?>" alt="<?=e($im['alt_text']??$perfume['name'])?>"><figcaption><?=!empty($im['is_primary'])?'Principal':''?> <form method="post" action="<?=url('admin/perfumes/'.$perfume['id'].'/imagenes/'.$im['id'].'/principal')?>"><?=csrf_field()?><button>Hacer principal</button></form><form method="post" action="<?=url('admin/perfumes/'.$perfume['id'].'/imagenes/'.$im['id'].'/eliminar')?>"><?=csrf_field()?><button>Eliminar</button></form></figcaption></figure><?php endforeach; ?></div><?php endif; ?><label>Agregar imagen <input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label>Texto alternativo<input name="image_alt" value=""></label><small>JPG, PNG o WebP. La primera imagen se marca como principal.</small></section><section class="panel form-section"><h2>SEO</h2><div class="form-grid"><label>Meta title<input name="meta_title" maxlength="180" value="<?=e($perfume['meta_title']??'')?>"></label><label>Meta description<input name="meta_description" maxlength="255" value="<?=e($perfume['meta_description']??'')?>"></label><label>Canonical URL<input type="url" name="canonical_url" value="<?=e($perfume['canonical_url']??'')?>"></label><label>Robots<select name="robots"><option>index,follow</option><option <?=($perfume['robots']??'')==='noindex,follow'?'selected':''?>>noindex,follow</option><option <?=($perfume['robots']??'')==='noindex,nofollow'?'selected':''?>>noindex,nofollow</option></select></label></div></section><div class="form-actions"><button class="admin-button primary" type="submit">Guardar como borrador</button><?php if($isEdit): ?><a class="admin-button secondary" href="<?=url('admin/perfumes/'.$perfume['id'])?>">Cancelar</a><?php endif; ?></div></form><?php $content=ob_get_clean();require dirname(__DIR__).'/layouts/main.php'; ?>
